		fmt.Println(1)
		return
	}
	if n == 3 {
		fmt.Println(2)
		return
	}
	if n == 4 {
		fmt.Println(2)
		return
	}

	// Generate Fibonacci numbers up to n
	fib := []int64{1, 2}
	for {
		next := fib[len(fib)-1] + fib[len(fib)-2]
		if next > n {
			break
		}
		fib = append(fib, next)
	}

	// Find the largest Fibonacci number <= n
	maxGames := 0
	for i := len(fib) - 1; i >= 0; i-- {
		if fib[i] <= n {
			maxGames = i + 1
			break
		}
	}

	fmt.Println(maxGames)
}
