package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int64
	fmt.Fscan(in, &n)

	// Fibonacci numbers
	fib := []int64{1, 1} // fib[0]=1, fib[1]=1
	for fib[len(fib)-1] < n {
		fib = append(fib, fib[len(fib)-1]+fib[len(fib)-2])
	}

	// Greedy decomposition
	remaining := n
	games := 0
	for i := len(fib) - 1; i >= 0 && remaining > 0; i-- {
		if fib[i] <= remaining {
			remaining -= fib[i]
			games++
		}
	}

	fmt.Println(games)
}
